# Project config for the agentic pipeline (generated by `agentic init`).
#
# The generic tool is the `agentic` Claude Code plugin (pet-claude marketplace).
# Everything specific to THIS project lives next to this file in .claude/agentic/:
#   config.sh   — this file
#   context.md  — what agents must know about the project (docs, rules, tools)
#   bin/        — project tools agents may call (runtime wrappers, renderers…)
#   runs/       — run logs (gitignored)
#
# Sourced by the plugin's libexec/*. Available: $REPO (main checkout), $EPIC (--epic),
# $PROJECT_DIR (this directory), $PROJECT_BIN ($PROJECT_DIR/bin), $AGENTIC_DIR (the tool).

PROJECT_NAME="{{PROJECT_NAME}}"

# --- Task queue -------------------------------------------------------------
# Task specs with YAML front-matter (id/status/depends_on). Relative to the repo.
TASKS_GLOB="{{TASKS_GLOB}}"
# Human-facing progress log; the pipeline rewrites the task's line in it.
PROGRESS_FILE="{{PROGRESS_FILE}}"
# Owner decisions that apply to every task, appended as acceptance criteria.
# Read from the main checkout, so edits apply from the next task on. Empty = none.
STANDING_CRITERIA="{{STANDING_CRITERIA}}"
# Project context for every agent. {{PROJECT_BIN}} in it is replaced with $PROJECT_BIN.
AGENT_CONTEXT="$PROJECT_DIR/context.md"
# Language of everything agents write for humans (summaries, progress, user-facing text).
LANGUAGE="{{LANGUAGE}}"

# --- Git --------------------------------------------------------------------
BASE_BRANCH="{{BASE_BRANCH}}"
WORK_BRANCH="auto/epic-${EPIC}"
# Isolated checkout the agents work in — your own working tree is never touched.
WORKTREE_DIR="$HOME/.cache/agentic/worktrees/$(basename "$REPO")-epic-${EPIC}"
# Push the branch and open/refresh a PR against BASE_BRANCH at the end of a run.
OPEN_PR={{OPEN_PR}}
# Push the branch after every task, so progress shows up on GitHub.
PUSH_EACH_TASK={{OPEN_PR}}
COMMIT_TRAILER="Co-Authored-By: Claude <noreply@anthropic.com>"

# --- Notifications ----------------------------------------------------------
# Called with one message argument on run start, every task result, errors and
# run end. Telegram credentials: ~/.config/agentic/telegram.env (notify-telegram --setup).
{{NOTIFY_LINE}}

# --- Worktree runtime -------------------------------------------------------
# Runs once per run, after the worktree is ready: install deps, create .env…
# $1 = worktree. Non-zero exit aborts the run.
project_setup() {
  local wt=$1
  : # e.g. (cd "$wt" && npm ci)
}

# Deterministic gate after every implementer attempt. Each entry is a shell
# command run from the worktree root; all must pass.
CHECKS=(
{{CHECKS}}
)

# --- Agents -----------------------------------------------------------------
# Empty = Claude Code default model.
PLANNER_MODEL=""
IMPLEMENTER_MODEL=""
VALIDATOR_MODEL=""

MAX_ATTEMPTS=3                    # implementer runs per task (each failed check/validation = 1)
AGENT_TIMEOUT="60m"               # wall clock per agent call
AGENT_BUDGET_USD={{AGENT_BUDGET}} # --max-budget-usd per agent call
RUN_BUDGET_USD={{RUN_BUDGET}}     # stop picking new tasks once the run has spent this much

# --- Permissions ------------------------------------------------------------
# On top of the tool's baseline (read-only shell, read-only git, checks, scratch).
# Project tools every role may call, e.g. "$PROJECT_BIN/run-tests *":
AGENT_BASH=(
)
IMPLEMENTER_EXTRA_BASH=(
  "mkdir *"
  "git mv *"
  "git rm *"
)
VALIDATOR_EXTRA_BASH=(
)
DENY_BASH=(
)

# --- Texts the pipeline writes (progress log, PR) — in the project language --
{{MESSAGES}}
